// Üretilen dosya: tool/ozgun/uret.py. Ekonomi ve Finans · Makroekonomi: milli gelir, büyüme, işsizlik (zor).
const ozEconomics8Zor = <(String, String, List<String>, String)>[
  ('Bir çiftçinin ürettiği buğdayın bir kısmını satmayıp kendi ailesinin tüketimine ayırması ulusal hesaplar sisteminde nasıl ele alınır?', 'Tahmini piyasa değeriyle üretime dâhil edilir', ['Satılmadığı için kesinlikle dışarıda bırakılır', 'Yalnızca yerel yönetim hesaplarına yazılır', 'Çiftçinin gelirinden düşülür'], 'Uluslararası ulusal hesaplar sistemi, kendi nihai kullanımı için üretilen malları (öz tüketim) tahmini değerle üretime katar. Ev içi hizmetler ise genellikle dışarıda kalır.'),
  ('Üretim yöntemiyle hesaplanan GSYH, sektörlerin katma değerleri toplamına hangi kalem eklenerek piyasa fiyatlarına ulaştırılır?', 'Ürünler üzerindeki vergiler eksi sübvansiyonlar', ['Transfer ödemeleri', 'Hanehalkı tasarrufları', 'Yurt dışında çalışan vatandaşların elde ettiği faktör gelirleri'], 'Sektörlerin katma değeri temel fiyatlarla ölçülür. KDV gibi ürün vergileri eklenip ürün sübvansiyonları düşülünce piyasa fiyatlarıyla GSYH bulunur.'),
  ('Ulusal hesaplarda kendi dükkânını işleten bir esnafın elde ettiği gelir, hem emeğinin hem de sermayesinin karşılığını birlikte içerdiği için hangi adla ayrı bir kalemde gösterilir?', 'Karma gelir', ['Emsal kira', 'Transfer geliri', 'Dağıtılmamış kâr'], 'Kendi hesabına çalışanların gelirinde ücret ile sermaye getirisi birbirinden ayrılamaz. Ulusal hesaplar bu geliri karma gelir olarak kaydeder.'),
  ('GSYH deflatörü, ağırlıkları her yıl o yılın üretim miktarlarına göre değiştiği için hangi tür fiyat endeksine benzer?', 'Paasche endeksi', ['Laspeyres endeksi', 'Bileşik faiz endeksi', 'Gini endeksi'], 'Paasche endeksi cari dönem miktarlarını ağırlık olarak kullanır. Deflatör de cari yıl üretim sepetini esas aldığından Paasche türü bir endekstir; TÜFE ise sabit sepetli Laspeyres türüne yakındır.'),
  ('Pek çok ülkenin istatistik kurumu reel GSYH\'yi tek bir sabit baz yılı yerine zincirleme hacim endeksleriyle hesaplar. Bunun temel gerekçesi nedir?', 'Göreli fiyatlar değiştikçe eski bir baz yılının büyümeyi çarpıtması', ['Zincirleme yöntemin hiçbir fiyat verisine gerek duymadan hesaplanabilmesi', 'Nominal GSYH\'nin artık yayımlanmaması', 'Baz yılının her zaman bir resesyon yılı olması'], 'Örneğin bilgisayar fiyatları hızla düşerken uzak bir baz yılının yüksek fiyatları kullanılırsa bu ürünlerin büyümeye katkısı abartılır. Zincirleme yöntem ağırlıkları her yıl güncelleyerek bu sapmayı azaltır.'),
  ('Dünya Bankası ülkeleri düşük, alt-orta, üst-orta ve yüksek gelirli gruplara ayırırken temel ölçüt olarak hangi göstergeyi kullanır?', 'Atlas yöntemiyle hesaplanan kişi başı GSMH', ['Toplam ihracat hacmi', 'Kişi başı elektrik tüketimi ve enerji kullanımı', 'İşsizlik oranı'], 'Dünya Bankası gelir sınıflandırmasında, kur dalgalanmalarını yumuşatan Atlas yöntemiyle dolara çevrilmiş kişi başı gayrisafi milli geliri (GNI) kullanır.'),
  ('SAGP ile yapılan uluslararası gelir karşılaştırmalarında kullanılan ve belirli bir yılda ABD dolarıyla aynı satın alma gücüne sahip olduğu varsayılan hesap birimine ne ad verilir?', 'Uluslararası dolar', ['Özel çekme hakkı', 'Avrupa para birimi', 'Altın dolar'], 'Geary-Khamis doları da denen uluslararası dolar, bir ülkede ABD dolarının ABD\'deki satın alma gücüne denk bir hesap birimidir. Özel çekme hakkı ise IMF\'nin rezerv varlığıdır.'),
  ('1934\'te ABD Kongresi\'ne sunduğu ilk milli gelir raporunda, bir ulusun refahının milli gelir ölçüsünden pek çıkarılamayacağı uyarısını yapan iktisatçı kimdir?', 'Simon Kuznets', ['John Maynard Keynes', 'Robert Solow', 'Milton Friedman'], 'ABD\'nin ilk resmî milli gelir tahminlerini hazırlayan Simon Kuznets, aynı raporda bu ölçünün bir refah göstergesi olarak kullanılmasına karşı uyarıda bulunmuştur.'),
  ('Fransa Cumhurbaşkanı Sarkozy\'nin girişimiyle kurulan ve 2009\'daki raporunda GSYH\'nin ötesinde refah ve sürdürülebilirlik ölçütleri öneren komisyonun başkanlığını hangi iktisatçı yürütmüştür?', 'Joseph Stiglitz', ['Paul Krugman', 'Thomas Piketty', 'Robert Lucas'], 'Ekonomik Performans ve Sosyal İlerlemenin Ölçümü Komisyonu\'na Joseph Stiglitz başkanlık etmiş, Amartya Sen danışman, Jean-Paul Fitoussi koordinatör olmuştur.'),
  ('Kişisel tüketimden başlayıp gelir eşitsizliği, suç ve kirlilik gibi maliyetleri düşen, ev içi emek ve gönüllü çalışma gibi değerleri ekleyen alternatif refah göstergesine ne ad verilir?', 'Gerçek İlerleme Göstergesi', ['Tüketici Güven Endeksi', 'Satın Alma Yöneticileri Endeksi', 'Herfindahl Endeksi'], 'Gerçek İlerleme Göstergesi (GPI), GSYH\'nin dışarıda bıraktığı sosyal ve çevresel maliyetleri ve kazançları hesaba katarak refahı daha kapsamlı ölçmeyi amaçlar.'),
  ('Bir ülkede yeni ilaçlar ve daha güvenli otomobiller gibi kalite iyileşmeleri yaşanırken fiyatlar da artıyor. İstatistikçilerin bu durumda karşılaştığı temel ölçüm güçlüğü nedir?', 'Fiyat artışının ne kadarının kaliteden kaynaklandığını ayırmak', ['Ürünlerin hangi yıl ve hangi fabrikada üretildiğini belirleyememek', 'İthalatı ihracattan ayırmak', 'Nüfus sayımını yapamamak'], 'Fiyat artışının bir bölümü daha iyi bir ürünün karşılığıdır. Bu kısım ayrılmazsa enflasyon abartılır, reel büyüme ve refah artışı olduğundan düşük ölçülür.'),
  ('Kayıt dışı ekonomiyi tahmin etmek için kullanılan parasal yaklaşım hangi varsayıma dayanır?', 'Kayıt dışı işlemlerin izi kalmasın diye büyük ölçüde nakitle yapıldığı', ['Kayıt dışı işlemlerin yalnızca kredi kartıyla yapıldığı', 'Kayıt dışı ekonominin ihracattan oluştuğu', 'Nakit kullanımının vergi oranlarından ve vergi denetiminden tamamen bağımsız olduğu'], 'Parasal (nakit talebi) yöntem, vergi yükü arttıkça dolaşımdaki nakdin olağandışı artmasını kayıt dışı faaliyetin göstergesi olarak yorumlar.'),
  ('Avrupa Birliği\'nin 2010 tarihli ulusal hesaplar sistemine (ESA 2010) geçişle birlikte üye ülkelerden, taraflar arasında rızaya dayalı uyuşturucu ticareti gibi yasa dışı faaliyetleri GSYH\'ye dâhil etmeleri istenmiştir. Bu düzenlemenin gerekçesi hangisidir?', 'Ülkeler arasında karşılaştırılabilirliği sağlamak', ['Bu faaliyetleri yasal hâle getirmek', 'Vergi gelirlerini doğrudan artırmak', 'Kayıt dışı ekonomiyi kısa sürede tamamen ortadan kaldırmak'], 'Bazı faaliyetler bir ülkede yasal, diğerinde yasa dışı olabilir. Hepsinin hesaba katılması ulusal hesapların ülkeler arasında aynı kapsamla hazırlanmasını sağlar.'),
  ('C = a + bY biçimindeki Keynesyen tüketim fonksiyonunda a pozitif ise gelir arttıkça ortalama tüketim eğilimi nasıl değişir?', 'Azalır', ['Artar', 'Sabit kalır', 'Önce sıfıra iner sonra artar'], 'OTE = a/Y + b\'dir. Gelir arttıkça a/Y küçüldüğü için ortalama tüketim eğilimi azalır ve marjinal eğilime yaklaşır.'),
  ('Simon Kuznets\'in ABD\'ye ait uzun dönem verileri, gelir yükselse de ortalama tüketim eğiliminin onlarca yıl boyunca yaklaşık sabit kaldığını göstermiştir. Bu bulgunun Keynesyen fonksiyonla çelişmesi iktisat literatüründe nasıl anılır?', 'Tüketim bulmacası', ['Tasarruf paradoksu', 'Leontief paradoksu', 'Değer paradoksu'], 'Kısa dönem ve kesit verileri OTE\'nin gelirle düştüğünü gösterirken uzun dönem verilerde sabit kalması \'tüketim bulmacası\' olarak anılır; sürekli gelir ve yaşam döngüsü kuramları bu bulmacayı açıklamak için geliştirilmiştir.'),
  ('Yaşam döngüsü kuramına göre bir ülkenin nüfusu yaşlandıkça ve emeklilerin oranı arttıkça toplam tasarruf oranı için ne beklenir?', 'Düşme eğilimine girmesi', ['Sürekli yükselmesi', 'Hiç değişmemesi', 'Sıfırdan küçük olamayacağı için sabitlenmesi'], 'Kurama göre emekliler birikimlerini harcar. Emekli payı arttıkça negatif tasarruf yapanların ağırlığı artar ve toplam tasarruf oranı düşer.'),
  ('Duesenberry\'nin nispi gelir hipotezine göre geliri düşen bir ailenin tüketimini hemen aynı oranda azaltmayıp daha önce ulaştığı en yüksek tüketim düzeyine tutunmasına ne ad verilir?', 'Mandal (cırcır) etkisi', ['Gösteriş etkisi', 'Pigou etkisi', 'Gelir etkisi'], 'Tüketim alışkanlıkları geçmişteki en yüksek gelir düzeyinde biçimlendiği için gelir düştüğünde tüketim aşağı doğru katıdır; bu mandal etkisidir.'),
  ('Kredi kullanma olanağı olmayan ve birikimi bulunmayan bir hane, geçici bir gelir artışını sürekli gelir kuramının öngördüğünden daha fazla harcayabilir. Bunun nedeni nedir?', 'Likidite kısıtı nedeniyle tüketimini gelecek gelirlere göre düzleştirememesi', ['Geçici gelirin vergiden muaf tutulması ve bu nedenle hane için daha değerli görünmesi', 'Marjinal tüketim eğiliminin sıfır olması', 'Faiz oranının sonsuz yükselmesi'], 'Borçlanamayan bir hane, istediği tüketimi zaten yapamamaktadır; eline geçen ek geliri hemen harcar. Likidite kısıtları sürekli gelir öngörüsünden sapmanın temel nedenidir.'),
  ('Robert Hall\'un 1978\'de sürekli gelir hipotezini rasyonel beklentilerle birleştirerek ulaştığı sonuca göre tüketimdeki değişmeler için hangisi doğrudur?', 'Önceden tahmin edilemez, rassal yürüyüş izler', ['Her yıl tam olarak aynı oranda artar', 'Gelirdeki değişmeyle birebir aynıdır', 'Faiz oranının iki katı kadar değişir'], 'Tüketiciler bildikleri her bilgiyi kullanıyorsa tüketim yalnızca beklenmedik haberlerle değişir; bu yüzden tüketimdeki değişmeler öngörülemez.'),
  ('Marjinal tüketim eğiliminin 0,8 olduğu bir ekonomide yatırımlar 100 milyon lira artıyor. Çarpan sürecinin üçüncü turunda (ilk harcamadan sonraki ikinci yeni harcama turunda) ortaya çıkan gelir artışı kaç milyon liradır?', '64', ['80', '100', '51,2'], 'İlk tur 100, ikinci tur 100 × 0,8 = 80, üçüncü tur 80 × 0,8 = 64 milyon liradır. Turlar giderek küçülür ve toplam 500 milyon liraya yaklaşır.'),
  ('Marjinal tüketim eğilimi 0,8 ve marjinal ithalat eğilimi 0,3 olan, vergisiz bir açık ekonomide ihracat 30 milyar lira artarsa denge geliri ne kadar artar?', '60 milyar lira', ['150 milyar lira', '30 milyar lira', '100 milyar lira'], 'Açık ekonomi çarpanı 1 / (1 − 0,8 + 0,3) = 1 / 0,5 = 2\'dir. Gelir artışı 30 × 2 = 60 milyar liradır.'),
  ('Marjinal tüketim eğilimi 0,8 ve gelir vergisi oranı yüzde 25 olan kapalı bir ekonomide yatırımlar 40 milyar lira artarsa denge geliri kaç milyar lira artar?', '100', ['200', '160', '40'], 'Vergili çarpan 1 / [1 − 0,8 × (1 − 0,25)] = 1 / 0,4 = 2,5\'tir. Gelir artışı 40 × 2,5 = 100 milyar liradır.'),
  ('Ekonomi tam istihdama yakın çalışırken toplam talebin artması durumunda çarpan etkisinin reel üretim üzerinde beklenenden zayıf kalmasının nedeni hangisidir?', 'Ek talebin büyük kısmı üretim yerine fiyat artışına dönüşür', ['Tüketicilerin marjinal tüketim eğilimi aniden 1\'e çıkar', 'Firmalar stoklarını sınırsız artırabilir', 'Bu durumda ithalat tamamen durur ve harcama zincirinde hiç sızıntı kalmaz'], 'Basit çarpan atıl kapasite varsayımına dayanır. Kapasite sınırına gelindiğinde firmalar üretimi artıramaz; talep artışı fiyatları yükseltir.'),
  ('Paul Samuelson\'ın 1939\'da ortaya koyduğu bir modele göre ekonomik dalgalanmalar hangi iki mekanizmanın etkileşimiyle açıklanabilir?', 'Çarpan ve hızlandıran', ['Arz ve talep esneklikleri', 'Enflasyon ve döviz kuru', 'Vergi ve transfer'], 'Çarpan-hızlandıran modelinde yatırım artışı geliri çarpan yoluyla artırır, gelir artışı da hızlandıran yoluyla yeni yatırımı tetikler. Bu etkileşim dalgalı bir gelir yolu üretebilir.'),
  ('Kısa dönem toplam arz eğrisinin pozitif eğimli olmasını açıklayan görüşlerden biri hangisidir?', 'Nominal ücretlerin sözleşmeler nedeniyle kısa dönemde yapışkan olması', ['Uzun dönemde teknolojinin sabit kalması', 'Toplam talebin fiyatlardan bağımsız olması ve hep aynı düzeyde kalması', 'Faiz oranlarının her zaman sıfır olması'], 'Fiyatlar yükselirken nominal ücretler sabit kalırsa reel ücret düşer ve firmalar daha fazla işçi çalıştırıp üretimi artırır; bu da pozitif eğim yaratır.'),
  ('Bir ekonomide toplam talep Y = 1.200 − 2P, kısa dönem toplam arz Y = 600 + 4P denklemleriyle verilmiştir. Denge fiyat düzeyi ve üretim hangisidir?', 'P = 100, Y = 1.000', ['P = 150, Y = 900', 'P = 50, Y = 1.100', 'P = 300, Y = 600'], '1.200 − 2P = 600 + 4P eşitliğinden 6P = 600, P = 100 bulunur. Y = 1.200 − 200 = 1.000.'),
  ('Toplam talep eğrisi tek bir malın talep eğrisinden farklı olarak neden \'diğer mallara geçiş\' (ikame) etkisiyle açıklanamaz?', 'Fiyat düzeyi değiştiğinde bütün malların fiyatı birlikte değişir', ['Toplam talep yalnızca ithal malları kapsar', 'Toplam talep eğrisi her zaman yatay çizildiği için ikame etkisine yer kalmaz', 'Tüketiciler toplam düzeyde hiç tasarruf yapmaz'], 'Tek bir malın fiyatı artınca tüketici başka mallara yönelir. Genel fiyat düzeyi değiştiğinde ise görece ucuzlayan bir yurt içi mal kalmadığından eğim servet, faiz ve dış ticaret etkileriyle açıklanır.'),
  ('NBER\'in resesyonu belirleme yaklaşımı, \'art arda iki çeyrek küçülme\' kuralından hangi yönüyle ayrılır?', 'İstihdam, gelir ve satışlar gibi birçok göstergeye bakar; tek bir kurala bağlı değildir', ['Yalnızca borsa endekslerine dayanır ve başka veri kullanmaz', 'Yalnızca yıllık enflasyon verilerine bakar', 'Ekonomideki her küçülmeyi, ne kadar kısa sürerse sürsün, resesyon sayar'], 'NBER resesyonu, ekonomiye yayılan ve birkaç aydan uzun süren belirgin bir faaliyet düşüşü olarak tanımlar ve bunu çok sayıda aylık göstergeyle değerlendirir.'),
  ('Yaklaşık 3-5 yıl süren ve büyük ölçüde firmaların stok ayarlamalarına bağlanan kısa konjonktür dalgaları kimin adıyla anılır?', 'Joseph Kitchin', ['Clément Juglar', 'Nikolay Kondratiev', 'Simon Kuznets'], 'Kitchin 1923\'te yaklaşık 40 aylık kısa dalgaları tanımlamış; bu dalgalar genellikle stok birikimi ve erimesiyle açıklanır.'),
  ('Yaklaşık 7-11 yıl süren ve sabit sermaye yatırımlarındaki dalgalanmalarla ilişkilendirilen orta vadeli konjonktür dalgaları kimin adıyla anılır?', 'Clément Juglar', ['Joseph Kitchin', 'Nikolay Kondratiev', 'Arthur Okun'], 'Fransız iktisatçı Juglar 19. yüzyılda kredi ve yatırımla bağlantılı, yaklaşık on yıllık dalgaları incelemiştir.'),
  ('Reel konjonktür kuramının temellerini atan çalışmalarıyla 2004 Nobel İktisat Ödülü\'nü paylaşan iktisatçılar kimlerdir?', 'Finn Kydland ve Edward Prescott', ['Robert Mundell ve Robert Fogel', 'George Akerlof ve Michael Spence', 'Daniel Kahneman ve Vernon Smith'], 'Kydland ve Prescott, iktisat politikasında zaman tutarlılığı ve konjonktür dalgalanmalarının itici güçleri üzerine çalışmalarıyla 2004 ödülünü almıştır.'),
  ('1980\'lerin ortasından 2007 krizine kadar ABD\'de üretim ve enflasyondaki dalgalanmaların belirgin biçimde azaldığı döneme ne ad verilir?', 'Büyük Ilımlılık', ['Büyük Buhran', 'Altın Çağ', 'Büyük Durgunluk'], 'Bu dönemde GSYH büyümesinin ve enflasyonun oynaklığı önceki on yıllara göre çok düşmüştür. 2008 krizi ve ardından gelen daralma ise Büyük Durgunluk olarak anılır.'),
  ('Bir ülkede İŞKUR\'a kayıtlı işsiz sayısı ile anketle ölçülen işsiz sayısının birbirinden farklı çıkmasının en makul nedeni hangisidir?', 'Her iş arayanın kayıt yaptırmaması, her kayıtlının da aktif iş aramaması', ['Anketin yalnızca kamu çalışanlarını kapsaması', 'İki kurumun farklı para birimleri kullanması', 'Anketin yalnızca üniversite mezunlarını sorgulaması ve diğerlerini dışarıda bırakması'], 'Kayıt verisi idari bir sayımdır; anket ise aktif arama ve işe hazır olma ölçütlerini uygular. İki kapsam örtüşmediği için sayılar farklıdır.'),
  ('TÜİK\'in \'atıl işgücü oranı\' hesaplanırken işsizlere hangi gruplar eklenir?', 'Zamana bağlı eksik istihdam ve potansiyel işgücü', ['Emekliler ve öğrenciler', 'Kayıt dışı çalışanlar ve memurlar', 'Ücretsiz aile işçileri ile işverenler ve kendi hesabına çalışanlar'], 'Atıl işgücü, standart işsizlik tanımının yakalayamadığı işgücü potansiyelini görmek için işsizlere eksik istihdamdakileri ve potansiyel işgücünü ekler.'),
  ('Bir ülkede işsizlik oranı düşük görünürken atıl işgücü oranının çok yüksek olması neyi gösterir?', 'Standart oranın işgücü piyasasındaki sıkıntıyı tam yansıtmadığını', ['Ülkede hiç kayıt dışı istihdam bulunmadığını', 'Ekonominin kapasitesinin üzerinde çalıştığını ve ücretlerin hızla arttığını', 'İşsizlik oranının yanlışlıkla iki kez hesaplandığını'], 'Çok sayıda kişi az saatle çalışıyor ya da iş aramaktan vazgeçmiş olabilir. Bu durum standart işsizlik oranında görünmez, atıl işgücü göstergesinde ortaya çıkar.'),
  ('Bir otomotiv sendikasının ücretleri denge düzeyinin üzerinde tutması sonucu, sendikalı sektörde iş bekleyen işçilerin başka sektörlerde çalışmak yerine sıra beklemesiyle oluşan işsizliğe ne ad verilir?', 'Bekleme işsizliği', ['Mevsimlik işsizlik', 'Gizli işsizlik', 'Teknolojik işsizlik'], 'Yüksek ücretli işlerde açılacak kadroları bekleyen işçiler başka işlere geçmez; ücretin denge üzerinde kalması nedeniyle oluşan bu işsizlik bekleme işsizliği olarak adlandırılır.'),
  ('İş arayanların uygun işi bulmak için zaman harcadığını, işverenlerin de uygun çalışanı aradığını ve bu eşleşme sürecinin işsizlik yarattığını gösteren \'arama ve eşleşme\' kuramı hangi yılın Nobel İktisat Ödülü\'ne konu olmuştur?', '2010', ['1976', '1995', '2017'], 'Peter Diamond, Dale Mortensen ve Christopher Pissarides, arama sürtünmeli piyasalar üzerine çalışmalarıyla 2010 Nobel İktisat Ödülü\'nü paylaşmıştır.'),
  ('Doğal işsizlik oranı kavramını 1960\'ların sonunda birbirinden bağımsız olarak geliştiren iki iktisatçı kimlerdir?', 'Milton Friedman ve Edmund Phelps', ['John Hicks ve Alvin Hansen', 'Robert Solow ve Paul Samuelson', 'Arthur Okun ve William Phillips'], 'Friedman 1968\'deki Amerikan İktisat Derneği başkanlık konuşmasında, Phelps ise 1967-68\'deki makalelerinde doğal oran fikrini ortaya koymuştur.'),
  ('Bir ülkede nüfusun büyük bölümünün genç olması doğal işsizlik oranını genellikle nasıl etkiler?', 'Yükseltir; gençler daha sık iş değiştirir ve arar', ['Düşürür; gençler hiç iş aramaz', 'Etkilemez; doğal oran yalnızca teknolojiyle belirlenir', 'Sıfıra indirir; gençlerin tamamı eğitimde olduğu için işgücüne girmez'], 'Gençler işgücü piyasasına yeni girer, uygun işi bulana kadar birkaç kez iş değiştirir. Bu da friksiyonel işsizliği ve doğal oranı artırır.'),
  ('Bir ülkede boş kadro sayısı değişmediği hâlde işsizlik sürekli yüksek kalıyor ve Beveridge eğrisi dışa doğru kayıyor. Bu kayma en çok neye işaret eder?', 'İş arayanlarla boş işlerin eşleşme etkinliğinin azaldığına', ['Toplam talebin aşırı arttığına', 'Ekonominin tam istihdamın üzerinde çalıştığına', 'Ücretlerin hızla düşüp piyasanın kendiliğinden dengelendiğine'], 'Aynı boş kadro oranında daha yüksek işsizlik, işsizlerin mevcut işlere yerleşmekte zorlandığını, yani beceri ya da bölge uyumsuzluğunun arttığını gösterir.'),
  ('Türkiye\'de işsizlik sigortasını kuran 4447 sayılı kanun hangi yıl kabul edilmiştir?', '1999', ['1965', '1984', '2008'], 'İşsizlik Sigortası Kanunu 1999\'da kabul edilmiş, prim kesintileri 2000\'de başlamış ve ilk ödenekler 2002\'de yapılmıştır.'),
  ('A. W. Phillips\'in 1958 tarihli ünlü makalesi İngiltere\'de yaklaşık bir asırlık veride hangi iki değişken arasındaki ilişkiyi incelemiştir?', 'Nominal ücretlerin değişim hızı ile işsizlik oranı', ['Faiz oranı ile yatırım miktarı', 'Döviz kuru ile ihracat hacmi', 'Kişi başı gelir ile nüfus artış hızı arasındaki ilişkiyi'], 'Phillips 1861-1957 dönemi İngiltere verilerinde işsizlik düşükken para ücretlerinin hızlı, yüksekken yavaş arttığını göstermiştir. Fiyat enflasyonuna uyarlanması sonradan yapılmıştır.'),
  ('Paul Samuelson ve Robert Solow\'un 1960\'ta Phillips ilişkisini ABD verilerine uyarlayıp fiyat enflasyonuyla ifade etmesi, politika yapıcılara hangi fikri sunmuştur?', 'Daha düşük işsizliğin daha yüksek enflasyonla \'satın alınabileceği\' bir seçenekler menüsü', ['Enflasyon ile işsizlik arasında hiçbir ilişki olmadığı fikri', 'İşsizliğin yalnızca para arzıyla belirlendiği, fiyat düzeyinin ise politika açısından hiç önemli olmadığı fikri', 'Enflasyonun her durumda işsizliği artırdığı fikri'], 'Samuelson ve Solow eğriyi, kamu otoritelerinin belirli bir enflasyon karşılığında belirli bir işsizlik oranı seçebileceği bir \'menü\' olarak yorumlamıştır.'),
  ('Friedman\'ın \'hızlanma hipotezine\' göre hükümet işsizliği kalıcı olarak doğal oranın altında tutmaya çalışırsa ne olur?', 'Enflasyon giderek hızlanır', ['Enflasyon sıfıra iner', 'İşsizlik kalıcı olarak doğal oranın altında kalır ve enflasyon değişmez', 'Doğal oran da aynı ölçüde düşer ve sorun ortadan kalkar'], 'İşçiler her seferinde beklentilerini yükseltir; işsizliği düşük tutmak için gerçekleşen enflasyonun beklentiyi sürekli aşması, yani hızlanması gerekir.'),
  ('İşten çıkarmanın yasal olarak zor ve pahalı olduğu ülkelerde Okun katsayısının (üretim değişmesine karşılık işsizlik değişmesinin) daha küçük çıkmasının nedeni nedir?', 'Firmalar üretim düştüğünde işçi çıkarmak yerine çalışma saatlerini azaltır', ['Bu ülkelerde işsizlik hiç ölçülmediği için', 'Bu ülkelerde üretim hiç dalgalanmadığı ve resesyon yaşanmadığı için katsayı hesaplanamaz', 'Bu ülkelerde işsizlik ödeneği yasak olduğu için'], 'İş güvencesi güçlü olduğunda üretim düşüşü işsizliğe değil, saat ve verimlilik ayarlamalarına yansır. Bu yüzden işsizlik üretime daha az duyarlıdır.'),
  ('Büyüme muhasebesi denklemi gY = 0,3gK + 0,7gL + gA biçimindedir. Bir yılda üretim yüzde 3,5, sermaye yüzde 4 ve emek yüzde 1 artmıştır. Toplam faktör verimliliği büyümesi (gA) yüzde kaçtır?', '1,6', ['3,5', '1,9', '2,3'], 'Sermayenin katkısı 0,3 × 4 = 1,2, emeğin katkısı 0,7 × 1 = 0,7 puandır. gA = 3,5 − 1,2 − 0,7 = 1,6.'),
  ('Büyüme muhasebesinde sermaye ve emeğin büyümesi, genellikle hangi ağırlıklarla çarpılarak üretim büyümesine katkıları bulunur?', 'Bu faktörlerin milli gelirdeki paylarıyla', ['Faktörlerin mutlak miktarlarıyla', 'Nüfus artış hızıyla', 'Faiz oranı ile enflasyon oranının toplamıyla'], 'Rekabetçi piyasalar varsayımıyla her faktörün üretim esnekliği, o faktörün gelir payına eşittir. Bu yüzden katkılar gelir paylarıyla ağırlıklandırılır.'),
  ('Paul Krugman\'ın 1994 tarihli \'Asya Mucizesi Efsanesi\' makalesinde Doğu Asya ekonomilerinin büyümesi hakkında ileri sürdüğü görüş hangisidir?', 'Büyümenin çoğunun verimlilikten değil, girdi birikiminden kaynaklandığı', ['Büyümenin tamamen doğal kaynak ihracatına dayandığı', 'Bu ülkelerin aslında hiç büyümediği ve verilerin yanlış olduğu', 'Büyümenin yalnızca yabancı yardımla finanse edildiği ve sürdürülebilir olduğu'], 'Krugman, Alwyn Young\'ın çalışmalarına dayanarak bu büyümenin Sovyet deneyimine benzer biçimde büyük ölçüde sermaye ve emek birikimiyle sağlandığını, bu yüzden yavaşlayacağını savunmuştur.'),
  ('Cobb-Douglas üretim fonksiyonu Y = A·K^α·L^(1−α) olan rekabetçi bir ekonomide α katsayısı neyi gösterir?', 'Sermayenin milli gelirden aldığı payı', ['Emeğin milli gelirden aldığı payı', 'Toplam faktör verimliliğinin düzeyini', 'Nüfusun ve işgücünün yıllık artış hızını'], 'Rekabetçi piyasalarda sermayeye marjinal ürünü ödenir; bu durumda sermaye gelirinin toplam gelire oranı α\'ya eşit çıkar. Emeğin payı ise 1 − α\'dır.'),
  ('Nicholas Kaldor\'un 1961\'de sıraladığı uzun dönem büyümeye ilişkin \'stilize olgular\' arasında aşağıdakilerden hangisi yer alır?', 'Sermaye-hasıla oranının uzun dönemde yaklaşık sabit kalması', ['İşçi başına üretimin uzun dönemde sabit kalması', 'Reel ücretlerin uzun dönemde sürekli düşmesi', 'Sermayenin getiri oranının sürekli ve çok hızlı biçimde artması'], 'Kaldor\'a göre işçi başı üretim ve sermaye sürekli artarken sermaye-hasıla oranı, sermayenin getiri oranı ve faktör gelir payları yaklaşık sabit kalır.'),
  ('Solow modelinde \'altın kural\' sermaye düzeyi neyi en yüksek düzeye çıkaran sermaye stokudur?', 'Durağan durumdaki işçi başına tüketimi', ['İşçi başına üretimi, tüketim ne olursa olsun', 'Tasarruf oranını', 'Amortisman oranını ve sermaye aşınmasını'], 'Daha fazla sermaye daha çok üretim sağlar ama daha çok yatırım da gerektirir. Altın kural, bu ikisi arasında tüketimi en büyük kılan dengeyi verir.'),
  ('Üretim fonksiyonu Cobb-Douglas ve sermayenin gelir payı 0,3 olan bir Solow ekonomisinde altın kural tasarruf oranı yüzde kaçtır?', '30', ['70', '3', '50'], 'Cobb-Douglas fonksiyonunda altın kural koşulu, tasarruf oranının sermayenin üretim esnekliğine (gelir payına) eşit olmasını gerektirir: s = α = 0,3.'),
  ('Neoklasik büyüme modeline adını veren Robert Solow bu alandaki katkıları nedeniyle Nobel İktisat Ödülü\'nü hangi yıl almıştır?', '1987', ['1970', '1995', '2001'], 'Solow, 1956 tarihli makalesiyle temelini attığı büyüme kuramına katkıları nedeniyle 1987\'de Nobel İktisat Ödülü\'nü almıştır.'),
  ('Solow ile aynı yıl, 1956\'da benzer bir neoklasik büyüme modeli yayımladığı için modelin onunla birlikte anıldığı Avustralyalı iktisatçı kimdir?', 'Trevor Swan', ['Roy Harrod', 'Nicholas Kaldor', 'Joan Robinson'], 'Bu nedenle model literatürde Solow-Swan modeli olarak da adlandırılır.'),
  ('Ülkeler arasındaki kişi başı gelir dağılımının zaman içinde daralmasına, yani gelirlerin standart sapmasının azalmasına ne ad verilir?', 'Sigma (σ) yakınsaması', ['Beta (β) yakınsaması', 'Mutlak ıraksama', 'Kuznets yakınsaması'], 'Beta yakınsaması yoksulların daha hızlı büyümesini anlatır; sigma yakınsaması ise gelirlerin birbirine gerçekten yaklaşıp dağılımın daraldığını ölçer.'),
  ('Romer\'e göre fikirleri ve bilgiyi büyümenin sürekli kaynağı yapan temel özellik hangisidir?', 'Aynı fikrin pek çok kişi tarafından aynı anda kullanılabilmesi', ['Fikirlerin tükenen fiziksel kaynaklar olması', 'Fikirlerin yalnızca devlet kurumları tarafından üretilip dağıtılabilmesi', 'Fikirlerin kullanıldıkça değer kaybetmesi ve eskimesi'], 'Fikirler tüketimde rakip olmayan mallardır: bir formülü bir firmanın kullanması başkasının kullanmasını engellemez. Bu özellik ölçeğe göre artan getiriler yaratır.'),
  ('Y = AK biçimindeki \'AK modeli\' gibi içsel büyüme modellerinde tasarruf oranındaki kalıcı bir artışın etkisi Solow modelinden nasıl ayrılır?', 'Uzun dönem büyüme hızını kalıcı olarak yükseltir', ['Hiçbir etkisi olmaz, büyüme hep sıfırdır', 'Yalnızca nüfus artış hızını değiştirir', 'Kısa dönemde büyümeyi düşürür, uzun dönemde hiçbir iz bırakmaz'], 'AK modelinde sermayenin getirisi azalmaz. Bu nedenle daha yüksek tasarruf ve yatırım, Solow modelindeki gibi yalnızca düzeyi değil, kalıcı büyüme hızını da artırır.'),
  ('Robert Lucas\'ın 1988 tarihli \'Ekonomik Kalkınmanın Mekaniği Üzerine\' makalesinde içsel büyümenin temel kaynağı olarak öne çıkardığı etken hangisidir?', 'Beşeri sermaye birikimi', ['Doğal kaynak ihracatı', 'Altın rezervleri', 'Tarımsal arazi genişlemesi ve sulama'], 'Lucas, eğitimle biriken beşeri sermayenin ve onun yarattığı dışsallıkların uzun dönem büyümeyi sürdürebileceğini göstermiştir.'),
  ('Yeniliğe dayalı ekonomik büyümeyi açıklayan çalışmaları nedeniyle 2025 Nobel İktisat Ödülü\'nü Joel Mokyr ile paylaşan, yaratıcı yıkım yoluyla sürdürülebilir büyüme kuramını geliştiren iki iktisatçı kimdir?', 'Philippe Aghion ve Peter Howitt', ['Ben Bernanke ve Douglas Diamond', 'Abhijit Banerjee ve Esther Duflo', 'Daron Acemoğlu ve James Robinson'], 'Aghion ve Howitt 1992\'de yaratıcı yıkımı biçimsel bir büyüme modeline dönüştürmüş; Mokyr ise teknolojik ilerlemenin tarihsel ön koşullarını incelemiştir.'),
  ('Kurumları \'bir toplumdaki oyunun kuralları\' olarak tanımlayan ve ekonomik tarihe yaklaşımıyla 1993 Nobel İktisat Ödülü\'nü paylaşan iktisatçı kimdir?', 'Douglass North', ['Ronald Coase', 'Oliver Williamson', 'Gary Becker'], 'North, Robert Fogel ile paylaştığı ödülü, kurumların ve işlem maliyetlerinin uzun dönem ekonomik performansı nasıl biçimlendirdiğini gösteren çalışmaları için almıştır.'),
  ('İnsani Gelişme Endeksi\'nin oluşturulmasına öncülük eden ve ilk İnsani Gelişme Raporu\'nu hazırlayan Pakistanlı iktisatçı kimdir?', 'Mahbub ul Haq', ['Muhammad Yunus', 'Amartya Sen', 'Abhijit Banerjee'], 'Mahbub ul Haq, 1990\'da BM Kalkınma Programı\'nda ilk raporu hazırlamış; Amartya Sen de yaklaşımın kuramsal temeline katkıda bulunmuştur.'),
  ('Gelir dağılımı ve yoksulluk istatistiklerinde hanehalkı gelirinin \'eşdeğer ölçek\' ile düzeltilmesinin amacı nedir?', 'Hanehalkı büyüklüğü ve bileşimi farklı olan haneleri karşılaştırılabilir kılmak', ['Gelirleri dolara çevirmek', 'Vergileri ve sosyal güvenlik primlerini gelirden düşerek hanenin brüt gelirini bulmak', 'Enflasyonun etkisini gidermek'], 'Kalabalık bir hanenin aynı toplam gelirle yaşam standardı daha düşüktür; ama ortak giderler nedeniyle kişi sayısıyla doğrudan bölmek de yanıltır. Eşdeğer ölçek bu ölçek ekonomisini hesaba katar.'),
  ('Palma oranı hangi iki grubun gelir paylarının oranıdır?', 'En zengin yüzde 10 ile en yoksul yüzde 40', ['En zengin yüzde 20 ile en yoksul yüzde 20', 'En zengin yüzde 1 ile en yoksul yüzde 99', 'Orta yüzde 50 ile en zengin yüzde 50'], 'José Gabriel Palma\'nın gözlemine göre orta gelir grubunun payı ülkeler arasında benzerdir; farklar uçlarda oluşur. Bu yüzden oran en zengin yüzde 10\'u en yoksul yüzde 40 ile karşılaştırır.'),
  ('İngiliz iktisatçı Anthony Atkinson\'ın geliştirdiği eşitsizlik endeksini Gini katsayısından ayıran temel özellik hangisidir?', 'Toplumun eşitsizliğe ne kadar duyarlı olduğunu gösteren bir parametre içermesi', ['Yalnızca servet verisiyle hesaplanması', 'Her zaman 1\'den büyük değer alması', 'Gelir yerine nüfus artışını ve doğurganlık oranını ölçmesi ve karşılaştırması'], 'Atkinson endeksi, bir \'eşitsizlikten kaçınma\' parametresi seçilerek hesaplanır; bu parametre yükseldikçe en yoksulların durumu endekse daha çok yansır.'),
  ('ABD\'de Büyük Buhran\'dan toparlanma sürerken 1937-1938\'de yaşanan ve sanayi üretiminin yeniden sert düştüğü dönem nasıl anılır?', 'Buhran içinde resesyon', ['Kükreyen Yirmiler', 'Büyük Ilımlılık dönemi ve istikrar', 'Altın Çağ'], '1937\'de harcamaların kısılması ve politikaların sıkılaştırılmasıyla toparlanma kesintiye uğramış, ekonomi yeniden daralmıştır; bu dönem \'Roosevelt resesyonu\' olarak da anılır.'),
  ('NBER\'e göre ABD\'de 2008 küresel krizine bağlı \'Büyük Durgunluk\' kaç ay sürmüştür?', '18 ay (Aralık 2007 – Haziran 2009)', ['6 ay (Ocak – Haziran 2009)', '36 ay (2008 – 2010)', '2 ay (Eylül – Ekim 2008)'], 'NBER, tepe noktasını Aralık 2007, dip noktasını Haziran 2009 olarak belirlemiştir; bu, İkinci Dünya Savaşı sonrasının en uzun resesyonudur.'),
  ('NBER\'in tarihlemesine göre ABD\'de COVID-19 salgınıyla başlayan 2020 resesyonu hangi özelliğiyle dikkat çeker?', 'Yalnızca iki ay sürerek kayıtlardaki en kısa resesyon olmuştur', ['On yıl sürerek en uzun resesyon olmuştur', 'Hiç işsizlik artışına yol açmamıştır', 'Üretim hiç düşmeden yalnızca fiyatların düştüğü, işsizliğin ise azaldığı bir resesyondur'], 'Tepe Şubat 2020, dip Nisan 2020 olarak belirlenmiştir. Daralma çok derin ama çok kısa sürmüştür.'),
  ('2020 yılında COVID-19 salgınına karşın, G20 ülkeleri arasında Çin ile birlikte yıllık bazda pozitif büyüme kaydeden ülke hangisidir?', 'Türkiye', ['Almanya', 'Hindistan', 'Brezilya'], 'Türkiye ekonomisi 2020\'de yaklaşık yüzde 2 büyümüş, G20\'de Çin dışında pozitif büyüyen tek ülke olmuştur; diğer üyelerin çoğu daralmıştır.'),
  ('Hindistan\'ın 1950\'lerden 1980\'e kadar yaklaşık yüzde 3,5 dolayında kalan düşük büyüme hızını anlatmak için iktisatçı Raj Krishna\'nın kullandığı ifade hangisidir?', 'Hindu büyüme hızı', ['Bollywood etkisi', 'Altın kural büyümesi', 'Kaplan büyümesi'], 'Raj Krishna bu ifadeyle Hindistan\'ın uzun süre nüfus artışının biraz üzerinde kalan büyümesini nitelemiştir; 1980\'ler ve özellikle 1991 reformları sonrasında büyüme hızlanmıştır.'),
  ('Potansiyel çıktı doğrudan gözlenemediği için sıklıkla istatistiksel yöntemlerle tahmin edilir. GSYH serisinden yumuşak bir eğilim çıkarmak için yaygın olarak kullanılan filtre hangisidir?', 'Hodrick-Prescott filtresi', ['Laspeyres filtresi', 'Lorenz yumuşatma filtresi', 'Phillips filtresi'], 'Hodrick-Prescott filtresi seriyi eğilim ve döngüsel bileşenlere ayırır; eğilim bileşeni çoğu zaman potansiyel çıktının yaklaşık bir göstergesi olarak kullanılır.'),
  ('Bir ülkede uzun bir durgunluk sırasında yatırımların ertelenmesi ve işsizlerin beceri yitirmesi potansiyel çıktıyı nasıl etkileyebilir?', 'Potansiyel çıktının kendisini de düşürebilir', ['Potansiyel çıktıyı kendiliğinden artırır', 'Yalnızca nominal GSYH\'yi etkiler, potansiyele dokunmaz', 'Potansiyel çıktıyı sonsuza dek sabitler ve hiç değiştirmez'], 'Sermaye birikiminin ve beşeri sermayenin zayıflaması, krizlerin kalıcı izler bırakarak üretim kapasitesini de küçültmesine yol açabilir.'),
  ('Klasik makroekonomide \'klasik ikilik\' olarak adlandırılan görüş hangisidir?', 'Reel değişkenlerin nominal değişkenlerden bağımsız olarak belirlendiği', ['İktisadın mikro ve makro olarak ikiye ayrıldığı', 'Ekonominin yalnızca tarım ve sanayiden oluştuğu', 'Devletin ve piyasanın her zaman çatıştığı ve uzlaşamadığı'], 'Klasik modelde üretim, istihdam ve reel faiz gibi reel büyüklükler para miktarından bağımsız belirlenir; para yalnızca fiyatlar gibi nominal büyüklükleri etkiler.'),
  ('Ekonomistlerin, resmî GSYH verisi açıklanmadan önce çok sayıda yüksek frekanslı veriyi kullanarak içinde bulunulan çeyreğin büyümesini tahmin etmesine ne ad verilir?', 'Anlık tahmin', ['Geriye dönük tahmin', 'Uzun dönem projeksiyon', 'Mevsimsel düzeltme ve arındırma'], 'Anlık tahmin, kartlı harcamalar, sanayi üretimi ve anketler gibi sık yayımlanan verilerle GSYH\'nin bugünkü durumunu kestirmeyi amaçlar.'),
  ('Ulusal hesapların uluslararası standartlarını belirleyen \'Ulusal Hesaplar Sistemi\'nin (SNA) geliştirilmesine öncülük ettiği için 1984 Nobel İktisat Ödülü\'nü alan İngiliz iktisatçı kimdir?', 'Richard Stone', ['James Meade', 'John Hicks', 'Nicholas Stern'], 'Richard Stone, savaş yıllarında Keynes\'le birlikte İngiltere\'nin ulusal gelir hesaplarını hazırlamış, ardından BM\'nin ilk ulusal hesaplar standardına öncülük etmiştir.'),
  ('Sektörler arasındaki mal ve hizmet akışlarını bir matris biçiminde göstererek her sektörün diğerlerinden ne kadar girdi kullandığını ortaya koyan yöntemi geliştirdiği için 1973 Nobel İktisat Ödülü\'nü alan iktisatçı kimdir?', 'Wassily Leontief', ['Simon Kuznets', 'Jan Tinbergen', 'Ragnar Frisch'], 'Leontief\'in girdi-çıktı analizi, bir sektördeki talep değişikliğinin bütün ekonomiye nasıl yayıldığını incelemek için ulusal hesaplarda yaygın olarak kullanılır.'),
  ('Girdi-çıktı tablosundan elde edilen bir \'çarpan\', bir sektörün nihai talebindeki 1 liralık artışın ekonomi genelinde ne kadar üretim artışına yol açtığını gösterir. Bu çarpanın 1\'den büyük çıkmasının nedeni nedir?', 'Sektörün diğer sektörlerden girdi talep etmesi ve onların da başka girdiler istemesi', ['Sektörün ürettiği her malın iki kez satılması', 'Fiyatların her aşamada iki katına çıkması', 'Devletin her harcamaya ek bir sübvansiyon eklemesi ve bu sayede bütün vergilerin kaldırılması'], 'Örneğin otomobil talebi çelik, lastik ve elektrik üretimini de artırır; bu dolaylı etkiler zincirleme biçimde toplam üretim etkisini büyütür.'),
  ('2008 tarihli uluslararası ulusal hesaplar standardıyla birlikte firmaların Ar-Ge harcamaları GSYH\'de nasıl ele alınmaya başlanmıştır?', 'Fikrî mülkiyet ürünlerine yapılan yatırım olarak', ['Ara tüketim olarak GSYH\'den düşülerek', 'Transfer ödemesi olarak', 'Hanehalkı tüketimi olarak ve hizmet kalemi altında'], '2008 SNA, Ar-Ge\'yi uzun süre üretimde kullanılan bir varlık yaratan harcama kabul edip sabit sermaye yatırımına dâhil etmiştir; bu değişiklik birçok ülkenin GSYH\'sini yükseltmiştir.'),
  ('2015\'te İrlanda\'nın GSYH\'si, büyük çok uluslu şirketlerin fikrî mülkiyet varlıklarını ülkeye taşıması nedeniyle yüzde 25\'in üzerinde büyümüş görünmüştür. Bu olay en çok hangi sonucu öne çıkarmıştır?', 'Küçük ve açık ekonomilerde GSYH\'nin halkın gelirini yansıtmakta yanıltıcı olabileceğini', ['İrlanda\'da hanehalklarının ortalama gelirlerinin yalnızca bir yıl içinde dörtte bir oranında arttığını', 'İrlanda\'da işsizliğin tamamen ortadan kalktığını', 'GSYH\'nin artık hiçbir ülkede hesaplanmaması gerektiğini ve kaldırılmasını'], 'Rakamın büyük kısmı şirket bilançolarındaki kayıtlardan kaynaklanmıştır. İrlanda bu yüzden çok uluslu şirket etkilerinden arındırılmış ayrı bir milli gelir ölçüsü (GNI*) yayımlamaya başlamıştır.'),
  ('Lüksemburg\'un kişi başı GSYH\'sinin, ülkede yaşayanların gerçek gelir düzeyini olduğundan yüksek göstermesinin önemli bir nedeni hangisidir?', 'Komşu ülkelerden her gün gelip çalışan çok sayıda kişinin üretime katılıp nüfusa sayılmaması', ['Ülkede hiç vergi alınmaması ve kamu hizmetlerinin tamamen özel sektör tarafından sunulması', 'Nüfusun çok hızlı artması', 'Ülkede hiç ithalat yapılmaması ve kapalı ekonomi olması'], 'Sınır ötesi çalışanların ürettiği değer GSYH\'ye girer, ama bu kişiler Lüksemburg nüfusunda yer almaz. Bölme işlemi bu nedenle kişi başı değeri şişirir.'),
  ('Singapur gibi bazı ülkelerde yıllık ihracatın GSYH\'den büyük olabilmesi nasıl açıklanır?', 'İhracat malların toplam değerini, GSYH ise yalnızca yurt içinde eklenen değeri ölçer', ['Bu ülkelerde GSYH yanlış hesaplanmaktadır', 'İhracat GSYH\'nin bir parçası olduğundan ondan büyük olamaz', 'Bu ülkeler hiç ithalat yapmadığı için ihracat ulusal hesaplarda iki kez sayılıp GSYH\'yi aşar'], 'İhraç edilen mallar büyük ölçüde ithal girdi içerir. İhracat bu girdilerin değerini de kapsarken GSYH, ithalat düşüldükten sonra kalan yurt içi katma değeri gösterir.'),
  ('Her ay çalışanların yüzde 1\'i işini kaybediyor, işsizlerin yüzde 9\'u iş buluyor. İşgücü sabitse uzun dönemde (durağan durumda) işsizlik oranı yüzde kaçta dengelenir?', '10', ['1', '9', '11,1'], 'Durağan durumda işini kaybedenler iş bulanlara eşittir: s × E = f × U. Buradan U / L = s / (s + f) = 0,01 / 0,10 = yüzde 10 bulunur.'),
  ('Keynes\'in 1930\'da yazdığı \'Torunlarımız İçin Ekonomik Olanaklar\' adlı denemesinde, emek kullanımını tasarruf etme yollarının yeni iş alanları bulunmasından hızlı gelişmesiyle oluşan işsizliği anlatmak için kullandığı kavram hangisidir?', 'Teknolojik işsizlik', ['Mevsimlik işsizlik', 'Gizli işsizlik', 'Gönüllü işsizlik'], 'Keynes bu denemede teknolojik işsizliğin geçici bir uyum sorunu olacağını, yüz yıl içinde verimlilik artışıyla insanların çok daha kısa çalışacağını öngörmüştür.'),
  ('Bir fabrika yatırımı yapıldıktan sonra kolayca geri satılamıyorsa, belirsizliğin arttığı dönemlerde firmaların yatırım kararını ertelemesi neden akılcıdır?', 'Bekleyerek yeni bilgi edinmenin bir değeri olduğu için', ['Faiz oranları belirsizlikte her zaman sıfıra indiği için', 'Yatırımın getirisi beklemekle kesin olarak iki katına çıktığı için', 'Devlet belirsizlik dönemlerinde yatırımı yasakladığı için'], 'Geri dönülmez yatırımlarda yanlış karar pahalıdır. Belirsizlik yüksekken beklemek, kötü senaryodan kaçınma olanağı sağlar; bu yüzden yatırım belirsizliğe çok duyarlıdır.'),
  ('Evsey Domar\'ın vurguladığı \'yatırımın ikili karakteri\' ne anlama gelir?', 'Yatırım hem bugünkü talebi artırır hem de gelecekteki üretim kapasitesini genişletir', ['Yatırım hem tasarrufu hem tüketimi azaltır', 'Yatırım yalnızca kamu ve yalnızca yabancılar tarafından yapılabilir', 'Yatırım hem fiyatları hem faizleri her zaman düşürür ve bu nedenle enflasyonu ortadan kaldırır'], 'Domar\'a göre yatırım kısa dönemde çarpan yoluyla toplam talebi, uzun dönemde ise sermaye stokunu artırarak arz kapasitesini büyütür; dengeli büyüme bu iki etkinin uyumuna bağlıdır.'),
  ('Claudia Sahm\'ın adıyla anılan \'Sahm kuralı\'na göre bir resesyonun başladığına dair erken sinyal hangisidir?', 'Üç aylık ortalama işsizlik oranının son on iki ayın en düşük düzeyinden 0,5 puan yükselmesi', ['Borsa endeksinin bir günde yüzde 10 düşmesi', 'Enflasyonun art arda üç ay yüzde 5\'i aşması', 'Faiz oranlarının bir yıl boyunca sabit kalması ve hiç değişmemesi'], 'Sahm kuralı, işsizlikteki hızlı artışın geçmişte resesyonların başlangıcıyla güçlü biçimde örtüştüğü gözlemine dayanır ve gerçek zamanlı bir gösterge olarak izlenir.'),
  ('Richard Koo\'nun Japonya\'nın 1990\'lardaki durgunluğunu açıklamak için kullandığı \'bilanço resesyonu\' kavramına göre firmalar faizler sıfıra yakınken bile neden borçlanıp yatırım yapmaz?', 'Varlık fiyatlarının çökmesiyle bozulan bilançolarını düzeltmek için borç ödemeye öncelik verdikleri için', ['Bankalar faiz almayı yasal olarak bıraktığı için', 'Japonya\'da yatırım yapmak yasaklandığı için', 'Firmalar ellerindeki nakdi tamamen ortaklarına dağıttıkları ve hiç kâr etmedikleri, ayrıca vergi yükü arttığı için'], 'Koo\'ya göre firmalar kâr en çoklaştırma yerine borç en azaltmaya yöneldiğinde düşük faiz yatırımı canlandıramaz ve toplam talep uzun süre zayıf kalır.'),
  ('Yaygın bir salgının hem fabrikaları kapatması hem de tüketicilerin harcamalarını kısması, toplam talep-toplam arz modelinde aynı anda hangi iki kaymaya yol açar?', 'Toplam talep sola, kısa dönem toplam arz da sola kayar', ['Toplam talep sağa, toplam arz sola kayar', 'İkisi de sağa kayar', 'Yalnızca uzun dönem toplam arz eğrisi sağa kayar ve fiyatlar düşer'], 'Bu durumda üretim kesin olarak düşer; fiyat düzeyinin yönü ise iki şokun göreli büyüklüğüne bağlıdır.'),
  ('Alexander Gerschenkron\'un 1962\'de ortaya koyduğu, geç sanayileşen ülkelerin öncülerin deneyiminden yararlanarak daha hızlı ilerleyebileceği fikri hangi adla anılır?', 'Geri kalmışlığın avantajı', ['Yoksulluğun kısır döngüsü', 'Büyük itme', 'Kaynak laneti ve Hollanda hastalığı'], 'Gerschenkron, Almanya ve Rusya gibi geç sanayileşenlerin hazır teknolojileri benimseyip bankalar ve devlet gibi kurumlarla bu açığı hızla kapatabildiğini savunmuştur.'),
  ('Bir ekonomide nominal GSYH bir yılda yüzde 40, GSYH deflatörü yüzde 25, nüfus yüzde 2 artmıştır. Kişi başı reel GSYH yaklaşık yüzde kaç artmıştır?', '9,8', ['13', '15', '12'], 'Reel GSYH 1,40 / 1,25 = 1,12 kat olmuştur. Kişi başına çevirmek için nüfus artışına bölünür: 1,12 / 1,02 ≈ 1,098, yani yaklaşık yüzde 9,8.'),
  ('Robert Solow\'un 1987\'de \'Bilgisayar çağını her yerde görüyoruz, verimlilik istatistikleri dışında\' sözüyle dile getirdiği durum hangi adla anılır?', 'Verimlilik paradoksu', ['Tasarruf paradoksu', 'Değer paradoksu', 'Leontief paradoksu'], 'Bilişim teknolojilerine büyük yatırım yapılmasına karşın verimlilik artışının istatistiklerde uzun süre belirgin olmaması \'Solow verimlilik paradoksu\' olarak bilinir.'),
  ('Gelir eşitsizliği yüksek ülkelerde ebeveyn geliri ile çocukların yetişkinlikteki geliri arasındaki bağın daha güçlü, yani kuşaklar arası hareketliliğin daha düşük olduğunu gösteren ilişkiye ne ad verilir?', 'Büyük Gatsby eğrisi', ['Lorenz eğrisi', 'Laffer eğrisi', 'Beveridge eğrisi'], 'Alan Krueger\'in 2012\'de yaygınlaştırdığı bu ilişki, eşitsizlik ile sosyal hareketlilik arasında ters yönlü bir bağ olduğunu ortaya koyar.'),
  ('Yeni Keynesyen iktisadın temel çabalarından biri hangisidir?', 'Fiyat ve ücret katılıklarını firmaların ve çalışanların akılcı davranışlarıyla açıklamak', ['Paranın hiçbir zaman reel etkisi olmadığını kanıtlamak', 'Toplam talebin üretim üzerinde etkisiz olduğunu göstermek', 'Devletin ekonomide hiçbir rolü olmaması gerektiğini ve piyasaların her zaman dengede olduğunu savunmak'], 'Yeni Keynesyenler menü maliyetleri, kademeli fiyat ayarlaması ve etkin ücret gibi mikro temellerle kısa dönemde fiyatların neden yapışkan olduğunu açıklar; bu da talep şoklarının üretimi etkilemesine yol açar.'),
  ('Kenneth Pomeranz\'ın 2000 tarihli kitabıyla yaygınlaşan ve 19. yüzyılda Batı Avrupa ile Çin gibi gelişmiş Asya bölgeleri arasında gelir düzeylerinin hızla ayrışmasını anlatan kavram hangisidir?', 'Büyük Ayrışma', ['Büyük Ilımlılık', 'Büyük Buhran', 'Büyük Yakınsama'], 'Pomeranz, 1800 dolaylarına kadar İngiltere ile Çin\'in en gelişmiş bölgeleri arasında büyük bir fark olmadığını, ayrışmanın kömür ve sömürgeler gibi etkenlerle sonradan derinleştiğini savunmuştur.'),
  ('Solow modelinde işgücü artarken yalnızca yeni işçilere mevcut düzeyde sermaye sağlamaya yetecek yatırıma \'sermaye genişlemesi\' denir. İşçi başına sermayeyi artıran yatırıma ne ad verilir?', 'Sermaye derinleşmesi', ['Sermaye aşınması', 'Sermaye kaçışı ve dış borçlanma', 'Sermaye ikamesi'], 'Sermaye derinleşmesi, her işçinin kullanabildiği makine ve teçhizat miktarını artırarak işçi başı üretimi yükseltir; genişleme ise yalnızca mevcut oranı korur.'),
  ('On kişilik bir toplumda yoksulluk sınırı 100 liradır ve yalnızca iki kişi bu sınırın altındadır; gelirleri 60 ve 80 liradır. Nüfusa göre normalleştirilmiş yoksulluk açığı endeksi yüzde kaçtır?', '6', ['30', '20', '60'], 'Her yoksulun açığı sınıra oranla (100 − 60) / 100 = 0,4 ve (100 − 80) / 100 = 0,2\'dir. Toplam 0,6 bütün nüfusa (10) bölünür: 0,06, yani yüzde 6.'),
  ('Kısa dönem Phillips eğrisi ile kısa dönem toplam arz eğrisi arasındaki ilişki en doğru nasıl ifade edilir?', 'Aynı ilişkiyi farklı değişkenlerle anlatan iki gösterimdir', ['Birbirinden tamamen bağımsız iki ayrı kavramdır', 'Phillips eğrisi uzun dönem toplam talebin gösterimidir', 'Toplam arz eğrisi yalnızca uzun dönemde, Phillips eğrisi yalnızca 19. yüzyılda geçerlidir'], 'Üretim potansiyelin üzerine çıktığında fiyatlar yükselir (toplam arz); bu sırada işsizlik doğal oranın altına iner ve enflasyon artar (Phillips eğrisi). Okun yasası iki gösterimi birbirine bağlar.'),
  ('Hollis Chenery ve Alan Strout\'un 1966 tarihli \'iki açık\' modeline göre gelişmekte olan ülkelerin büyümesini sınırlayan iki darboğaz hangileridir?', 'Tasarruf açığı ve döviz açığı', ['Bütçe açığı ve enflasyon açığı', 'Nüfus açığı ve toprak açığı', 'İşsizlik açığı ve ücret açığı'], 'Model, büyüme için gereken yatırımın hem yetersiz yurt içi tasarruf hem de ithal sermaye malları için gereken döviz yetersizliğiyle kısıtlanabileceğini, dış yardımın bu açıkları kapatabileceğini savunur.'),
  ('1970\'lerin sonu ve 1980\'lerde Batı Avrupa\'da işgücü piyasası katılıkları nedeniyle yüksek ve inatçı işsizliğin sürmesini anlatmak için kullanılan terim hangisidir?', 'Avrupa sklerozu', ['Hollanda hastalığı', 'Japon mucizesi', 'Kükreyen yirmiler ve Altın Çağ'], 'Herbert Giersch\'in yaygınlaştırdığı bu terim, katı iş güvencesi kuralları ve yüksek işsizlik ödenekleri gibi etkenlerin Avrupa\'da istihdam artışını yavaşlattığı görüşünü anlatır.'),
  ('2010\'dan bu yana İnsani Gelişme Endeksi, sağlık, eğitim ve gelir boyutlarına ait alt endekslerin hangi ortalaması alınarak hesaplanmaktadır?', 'Geometrik ortalama', ['Aritmetik ortalama', 'Ağırlıklı toplam', 'En yüksek alt endeksin değeri ve en düşüğünün farkı'], 'Geometrik ortalama, bir boyuttaki düşük başarının diğerlerindeki yüksek başarıyla tamamen telafi edilmesini önler; 2010 öncesinde aritmetik ortalama kullanılıyordu.'),
  ('Gini katsayısı aynı olan iki ülkenin gelir dağılımları için hangisi kesin olarak söylenebilir?', 'Lorenz eğrileri ile eşitlik doğrusu arasındaki alanlar eşittir', ['İki ülkenin gelir dağılımı her bakımdan aynıdır', 'İki ülkenin ortalama gelirleri eşittir', 'İki ülkenin yoksulluk oranları ve en zengin yüzde 10\'un payları kesinlikle aynıdır'], 'Gini katsayısı tek bir özet sayıdır; aynı alanı farklı biçimli Lorenz eğrileri de verebilir. Bu yüzden eşitsizliğin hangi gelir grubunda yoğunlaştığı farklı olabilir.'),
  ('NBER resesyonları belirlerken ekonomik faaliyetteki düşüşü hangi üç ölçüte göre değerlendirir?', 'Derinlik, yaygınlık ve süre', ['Faiz, kur ve enflasyon', 'Nüfus, göç ve doğurganlık', 'İhracat, ithalat ve rezervler'], 'Bir düşüşün resesyon sayılması için yeterince derin, ekonomiye yayılmış ve birkaç aydan uzun sürmüş olması gerekir; ölçütlerden biri çok güçlüyse diğerlerinin zayıflığı telafi edilebilir.'),
  ('Keynes\'in fikirlerini IS-LM modeli biçiminde formüle eden 1937 tarihli \'Bay Keynes ve Klasikler\' makalesinin yazarı kimdir?', 'John Hicks', ['Alvin Hansen', 'Joan Robinson', 'Piero Sraffa'], 'Hicks\'in makalesi, Keynes\'in Genel Teori\'sini mal ve para piyasalarının eş anlı dengesine indirgeyen IS-LM çerçevesini başlatmış; model daha sonra Alvin Hansen tarafından yaygınlaştırılmıştır.'),
  ('Bir ailenin bir müteahhide para vermeden, kendi emeğiyle ve satın aldığı malzemelerle kullanmak üzere köy evi inşa etmesi ulusal hesaplarda nasıl ele alınır?', 'Kendi hesabına üretim olarak yatırıma dâhil edilir', ['Piyasada satılmadığı için hiçbir şekilde hesaba katılmaz', 'Ev işi sayılarak GSYH dışında bırakılır', 'Transfer ödemesi olarak kaydedilir ve kamu hesabına yazılır'], 'Ulusal hesaplar sistemi, hanehalklarının kendi kullanımları için yaptıkları konut inşaatını sabit sermaye oluşumu olarak tahmini değeriyle üretime katar.'),
  ('Ekonomik faaliyetin daraldığı bir dönemde firmaların, toparlanmada yeniden bulmanın zor olacağı nitelikli çalışanlarını işten çıkarmayıp tutmasına ne ad verilir?', 'Emek istifçiliği', ['Gizli işsizlik', 'Bekleme işsizliği', 'Eksik istihdam ve kısmi zamanlı çalışma'], 'Emek istifçiliği, işe alma ve eğitim maliyetlerinden kaçınmak için çalışanların düşük kapasiteyle de olsa elde tutulmasıdır; bu nedenle verimlilik resesyonlarda düşme eğilimindedir.'),
  ('Bir ekonomide nominal ücretler ile emek verimliliği aynı oranda artarsa, diğer koşullar sabitken kısa dönem toplam arz eğrisi nasıl etkilenir?', 'Kaymaz, çünkü birim emek maliyeti değişmez', ['Mutlaka sola kayar', 'Mutlaka sağa kayar', 'Dikey hâle gelir ve fiyatlar sonsuza kadar artar'], 'Firmalar için önemli olan, ücretin çalışanın ürettiği miktara oranıdır. Ücret ve verimlilik birlikte arttığında birim maliyet sabit kalır ve arz eğrisi yerinde durur.'),
  ('Bir hükümetin açıkladığı büyüme rakamlarının güvenilirliğini dışarıdan sınamak isteyen araştırmacıların uydu görüntülerinden gece ışıklarının yoğunluğunu kullanmasının mantığı nedir?', 'Ekonomik faaliyet arttıkça elektrik kullanımı ve gece aydınlatmasının da artması', ['Gece ışıklarının nüfusu birebir ölçmesi', 'Işıkların yalnızca enflasyonla ilişkili olması', 'Uydu verisinin resmî GSYH\'nin yasal kaynağı olması ve istatistik kurumunun yerini alması'], 'Gece ışıkları GSYH ile güçlü biçimde ilişkilidir ve manipüle edilmesi zordur; bu nedenle istatistiklerin zayıf ya da tartışmalı olduğu ülkelerde bağımsız bir gösterge olarak kullanılır.'),
  ('Keynes, durgunlukta nominal ücretlerin düşürülmesinin işsizliği mutlaka azaltmayacağını savunmuştur. Bunun temel gerekçesi hangisidir?', 'Ücret düşüşü işçilerin gelirini ve harcamalarını azaltarak toplam talebi daha da zayıflatabilir', ['Ücretlerin düşürülmesi yasal olarak yasak olduğu için', 'İşverenlerin daha düşük ücretle hiç kimseyi çalıştırmak istememesi nedeniyle', 'Ücret düşüşü kesin olarak faizleri yükselttiği ve yatırımları her durumda durdurduğu için'], 'Ücretler firmalar için maliyet, hanehalkları için gelirdir. Keynes\'e göre genel bir ücret indirimi talebi düşürerek firmaların satışlarını ve istihdam isteğini azaltabilir.'),
  ('Ekonomik dalgalanmaların büyük ölçüde talep şoklarından kaynaklandığını savunan iktisatçılar ile verimlilik şoklarından kaynaklandığını savunanlar arasındaki tartışma en çok hangi soru etrafında yoğunlaşır?', 'Durgunluklarda devlet müdahalesinin gerekli ve yararlı olup olmadığı', ['GSYH\'nin nasıl adlandırılacağı', 'İşsizliğin hangi kurum tarafından açıklanacağı', 'Baz yılının hangi yıl seçileceği ve endeksin adı'], 'Dalgalanmalar etkin tepkilerse müdahale gereksiz olabilir; talep yetersizliğinden kaynaklanıyorsa toplam talebi destekleyen politikalar refahı artırabilir.'),
  ('Ekonomik büyümenin ve kalkınmanın uzun dönemde ölçülmesinde, yalnızca bugünkü GSYH\'ye değil ülkenin servet stokuna (fiziki, beşeri ve doğal sermaye) da bakılmasının gerekçesi nedir?', 'Bugünkü yüksek üretim, gelecekteki üretim kapasitesini tüketerek de elde edilebilir', ['Servet stoku her zaman GSYH\'ye eşittir', 'GSYH zaten servet stokunu ölçer', 'Servet stokunun ekonomiyle hiçbir ilgisi yoktur'], 'Örneğin ormanları hızla keserek ya da altyapıyı yenilemeden yüksek GSYH sağlanabilir; servet ölçüleri büyümenin sürdürülebilir olup olmadığını gösterir.'),
  ('Birçok ülkede hanehalkları arasındaki tüketim eşitsizliğinin gelir eşitsizliğinden daha düşük çıkmasının bir nedeni hangisidir?', 'Hanelerin borçlanma ve birikim kullanarak tüketimlerini zaman içinde dengelemesi', ['Tüketimin hiçbir ülkede ölçülmemesi', 'Yüksek gelirlilerin gelirlerinin tamamını tüketmesi', 'Bütün hanelerin aynı miktarda tükettiğinin yasayla zorunlu tutulması'], 'Geçici gelir dalgalanmaları tüketime tam yansımaz; gelirleri geçici olarak düşen haneler birikimlerini kullanır. Ayrıca yüksek gelirliler gelirlerinin daha büyük kısmını tasarruf eder.'),
  ('Kamu hizmetlerinin GSYH\'de girdi maliyetiyle ölçülmesi, kamu sektöründeki verimlilik artışlarının ölçülmesi açısından hangi sorunu doğurur?', 'Aynı maliyetle daha iyi hizmet sunulsa bile ölçülen üretim değişmez', ['Kamu hizmetleri iki kez sayılır', 'Kamu sektörünün verimliliği her zaman sonsuz görünür', 'Kamu çalışanlarının maaşları GSYH\'den düşülür ve üretim negatif çıkar'], 'Üretim girdilerle ölçüldüğünde, örneğin aynı sayıda öğretmenle daha iyi eğitim verilmesi istatistiklere yansımaz; bu nedenle kamu verimliliği ölçümü güçtür.'),
  ('Ulusal hesaplarda \'nihai tüketim harcaması\' kavramına hangi kesimlerin harcamaları dâhil edilir?', 'Hanehalkları, hanehalkına hizmet eden kâr amacı gütmeyen kuruluşlar ve devlet', ['Yalnızca firmalar', 'Yalnızca yabancı turistler', 'Yalnızca bankalar, sigorta şirketleri ve büyük holdingler ile onların iştirakleri'], 'Nihai tüketim; hanehalklarının, dernek ve vakıf gibi kâr amacı gütmeyen kuruluşların ve genel yönetimin mal ve hizmetlere yaptığı harcamaları kapsar. Firmaların harcamaları ara tüketim ya da yatırımdır.'),
  ('1993 tarihli Ulusal Hesaplar Sistemi ile birlikte gayrisafi milli hasılanın (GSMH) yerine kullanılmaya başlanan ve kavramsal olarak ona karşılık gelen terim hangisidir?', 'Gayrisafi milli gelir (GNI)', ['Gayrisafi yurt içi hasıla (GDP)', 'Net yurt içi hasıla', 'Kişi başı kullanılabilir gelir ve tüketim'], 'Vatandaşların ve yerleşiklerin elde ettiği gelire odaklanan bu büyüklüğün bir üretim değil gelir kavramı olduğunu vurgulamak için \'milli hasıla\' yerine \'milli gelir\' terimi benimsenmiştir.'),
];
